package com.ccb.testmanagement.execution;

import com.ccb.attachment.integration.AttachmentBindingCommand;
import com.ccb.attachment.integration.AttachmentGateway;
import com.ccb.common.api.PageQuery;
import com.ccb.common.api.PageResult;
import com.ccb.common.exception.BusinessException;
import com.ccb.common.exception.ErrorCode;
import com.ccb.security.model.AuthUser;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.util.concurrent.atomic.AtomicLong;

@Service
public class TestExecutionService {
  public static final String BUSINESS_TYPE="TEST_EXECUTION";
  private static final Set<String> DOMAINS=Set.of("application-assembly","user-testing","non-functional","security"), STATUSES=Set.of("UNEXECUTED","RUNNING","SUCCESS","FAILED","INVALID","BLOCKED");
  private static final AtomicLong IDS=new AtomicLong(System.currentTimeMillis()*1000);
  private final TestExecutionRepository repository; private final AttachmentGateway attachments; private final ObjectMapper objectMapper;
  public TestExecutionService(TestExecutionRepository repository,AttachmentGateway attachments,ObjectMapper objectMapper){this.repository=repository;this.attachments=attachments;this.objectMapper=objectMapper;}
  public Map<String,Object> tree(String domain,long projectId,AuthUser user){scope(domain,projectId,user);Map<String,Object> p=p(user,domain,projectId);return Map.of("systems",repository.systems(p),"rounds",repository.rounds(p),"cycles",repository.cycles(p),"directories",repository.directories(p));}
  public PageResult<Map<String,Object>> list(String domain,long projectId,Long system,Long round,Long cycle,Long directory,String keyword,Collection<String> statuses,Long executor,String defectLink,String validity,String sortBy,String sortOrder,PageQuery page,AuthUser user){scope(domain,projectId,user);if(system!=null)enabled(domain,projectId,system,user.tenantId());if(round!=null)round(round,domain,projectId,user.tenantId());if(cycle!=null)cycle(cycle,domain,projectId,user.tenantId());if(directory!=null)directory(directory,domain,projectId,user.tenantId());Map<String,Object> p=p(user,domain,projectId);p.put("systemId",system);p.put("roundId",round);p.put("cycleId",cycle);p.put("directoryId",directory);p.put("keyword",text(keyword,200,"关键字"));p.put("executorId",executor);p.put("statuses",statuses==null?List.of():statuses.stream().map(x->status(x)).toList());p.put("defectLink",defectLink);p.put("validity",validity);p.put("sortBy",sortBy);p.put("ascending","ascending".equalsIgnoreCase(sortOrder));p.put("offset",(page.page()-1)*page.size());p.put("size",page.size());return new PageResult<>(repository.executions(p),repository.executionCount(p),page.page(),page.size());}
  public Map<String,Object> previewImport(String domain,long projectId,Map<String,Object> body,AuthUser user){scope(domain,projectId,user);long directoryId=positive(body.get("directory_id"),"目标执行目录");Map<String,Object> directory=directory(directoryId,domain,projectId,user.tenantId());Set<Long> ids=new LinkedHashSet<>();List<Map<String,Object>> invalid=new ArrayList<>();for(Object id:list(body.get("case_ids")))ids.add(positive(id,"案例"));for(Object scope:list(body.get("scope_ids")))ids.addAll(repository.caseIdsByScope(with(p(user,domain,projectId),"scopeId",positive(scope,"范围"))));for(String code:codes(body.get("case_codes"))){List<Long> rows=repository.caseIdsByCode(with(p(user,domain,projectId),"caseCode",code));if(rows.isEmpty())invalid.add(Map.of("case_code",code,"reason","案例编号不存在或不属于当前项目"));else ids.addAll(rows);}List<Map<String,Object>> valid=new ArrayList<>(), duplicates=new ArrayList<>();for(Long id:ids){Map<String,Object> testCase=repository.testCase(with(p(user,domain,projectId),"caseId",id));if(testCase==null){invalid.add(Map.of("case_id",id,"reason","案例不存在"));continue;}if(number(testCase.get("physical_subsystem_id"))!=number(directory.get("physical_subsystem_id"))){invalid.add(Map.of("case_code",testCase.get("case_code"),"reason","案例不属于当前系统"));continue;}if(bool(testCase.get("invalidated"))){invalid.add(Map.of("case_code",testCase.get("case_code"),"reason","案例已无效"));continue;}if(repository.existsInDirectory(with(with(p(user,domain,projectId),"directoryId",directoryId),"caseId",id)))duplicates.add(testCase);else valid.add(testCase);}return Map.of("directory_id",directoryId,"valid",valid,"duplicates",duplicates,"invalid",invalid,"valid_count",valid.size());}
  @Transactional public Map<String,Object> confirmImport(String domain,long projectId,Map<String,Object> body,AuthUser user){Map<String,Object> preview=previewImport(domain,projectId,body,user);long directoryId=number(preview.get("directory_id"));Map<String,Object> dir=directory(directoryId,domain,projectId,user.tenantId());int created=0;for(Map<String,Object> c:maps(preview.get("valid"))){Map<String,Object> row=p(user,domain,projectId);row.put("id",next());row.put("directoryId",directoryId);row.put("caseId",c.get("id"));row.put("systemId",dir.get("physical_subsystem_id"));row.put("roundId",dir.get("round_id"));row.put("cycleId",dir.get("cycle_id"));repository.insertExecution(row);trace(domain,projectId,number(row.get("id")),"IMPORT",user,Map.of("case_code",c.get("case_code")));created++;}return Map.of("created",created,"skipped_duplicates",maps(preview.get("duplicates")).size(),"invalid",maps(preview.get("invalid")).size());}
  @Transactional public Map<String,Object> saveDirectory(String domain,long projectId,Long id,Map<String,Object> body,AuthUser user){scope(domain,projectId,user);long system=positive(body.get("physical_subsystem_id"),"参测系统"),round=positive(body.get("round_id"),"轮次"),cycle=positive(body.get("cycle_id"),"周期");enabled(domain,projectId,system,user.tenantId());round(round,domain,projectId,user.tenantId());cycle(cycle,domain,projectId,user.tenantId());Long parent=nullable(body.get("parent_id"));if(parent!=null){Map<String,Object> existing=directory(parent,domain,projectId,user.tenantId());if(number(existing.get("physical_subsystem_id"))!=system||number(existing.get("cycle_id"))!=cycle)throw bad("父目录必须属于相同系统和周期");}Map<String,Object> row=p(user,domain,projectId);row.put("id",id==null?next():id);row.put("systemId",system);row.put("roundId",round);row.put("cycleId",cycle);row.put("parentId",parent);row.put("name",required(body.get("directory_name"),"目录名称",100));row.put("sort",integer(body.get("sort_no")));if(id==null)repository.insertDirectory(row);else{directory(id,domain,projectId,user.tenantId());repository.updateDirectory(row);}return directory(number(row.get("id")),domain,projectId,user.tenantId());}
  @Transactional public void deleteDirectory(String domain,long projectId,long id,AuthUser user){directory(id,domain,projectId,user.tenantId());Map<String,Object> p=with(p(user,domain,projectId),"directoryId",id);if(repository.directoryHasExecutions(p)||repository.directoryHasChildren(p))throw conflict("该目录下已有执行记录或子目录，禁止删除");repository.deleteDirectory(with(p,"id",id));}
  public Map<String,Object> detail(String domain,long projectId,long id,AuthUser user){execution(id,domain,projectId,user.tenantId());Map<String,Object> p=with(p(user,domain,projectId),"id",id);Map<String,Object> result=new LinkedHashMap<>(repository.executionDetail(p));result.put("attachments",repository.attachmentRows(p));result.put("defects",repository.defects(p));result.put("traces",repository.traces(p));return result;}
  @Transactional public Map<String,Object> saveResult(String domain,long projectId,long id,Map<String,Object> body,AuthUser user){Map<String,Object> execution=execution(id,domain,projectId,user.tenantId());writeAllowed(domain,projectId,number(execution.get("physical_subsystem_id")),user);String state=status(body.get("execution_status")),actual=body.containsKey("actual_result_html")?html(body.get("actual_result_html")):(String)execution.get("actual_result_html"),remark=body.containsKey("remark_html")?html(body.get("remark_html")):(String)execution.get("remark_html");Set<Long> defects=ids(body.get("defect_ids"));if(("INVALID".equals(state)||"BLOCKED".equals(state))&&plain(remark).isBlank())throw bad("无效或阻塞时备注必填");if("FAILED".equals(state)&&defects.isEmpty()&&!repository.hasActiveDefects(with(p(user,domain,projectId),"executionId",id)))throw bad("失败必须关联或新建缺陷");if(!defects.isEmpty())associate(id,defects,domain,projectId,user);Map<String,Object> row=with(p(user,domain,projectId),"id",id);row.put("status",state);row.put("actual",actual);row.put("remark",remark);repository.updateResult(row);if(body.containsKey("attachment_ids"))syncAttachments(id,body.get("attachment_ids"),user);trace(domain,projectId,id,"SAVE_RESULT",user,Map.of("old_status",String.valueOf(execution.get("execution_status")),"new_status",state));return detail(domain,projectId,id,user);}
  @Transactional public Map<String,Object> batchStatus(String d,long p,Map<String,Object> b,AuthUser u){Set<Long> selected=ids(b.get("ids"));if(selected.isEmpty())throw bad("请选择执行记录");for(long id:selected)saveResult(d,p,id,b,u);return Map.of("changed",selected.size());}
  @Transactional public Map<String,Object> move(String d,long p,Collection<Long> ids,long target,AuthUser u){Map<String,Object> targetDir=directory(target,d,p,u.tenantId());manager(d,u);int moved=0;for(long id:ids){Map<String,Object> execution=execution(id,d,p,u.tenantId());if(number(execution.get("physical_subsystem_id"))!=number(targetDir.get("physical_subsystem_id"))||number(execution.get("cycle_id"))!=number(targetDir.get("cycle_id")))throw bad("目标目录必须属于相同系统和周期");repository.moveExecution(with(with(p(u,d,p),"id",id),"directoryId",target));trace(d,p,id,"MOVE",u,Map.of("target_directory_id",target));moved++;}return Map.of("moved",moved);}
  @Transactional public Map<String,Object> remove(String d,long p,Collection<Long> ids,AuthUser u){manager(d,u);List<Long> blocked=new ArrayList<>();int removed=0;for(long id:ids){execution(id,d,p,u.tenantId());if(repository.hasUnresolvedDefects(with(p(u,d,p),"executionId",id))){blocked.add(id);continue;}snapshot(id,u);repository.removeExecution(with(p(u,d,p),"id",id));removed++;}return Map.of("removed",removed,"blocked_execution_ids",blocked);}
  @Transactional public void associate(long executionId,Collection<Long> defectIds,String d,long p,AuthUser u){execution(executionId,d,p,u.tenantId());for(long defectId:defectIds){Map<String,Object> relation=with(with(p(u,d,p),"executionId",executionId),"defectId",defectId);if(!repository.defectExists(relation))throw bad("缺陷不存在或不属于当前项目");if(!repository.hasActiveDefects(relation)){relation.put("id",next());repository.insertRelation(relation);}}trace(d,p,executionId,"ASSOCIATE_DEFECT",u,Map.of("defect_ids",defectIds));}
  @Transactional public void detach(long executionId,long defectId,String d,long p,AuthUser u){manager(d,u);execution(executionId,d,p,u.tenantId());Map<String,Object> relation=with(with(p(u,d,p),"executionId",executionId),"defectId",defectId);if(!repository.hasActiveDefects(relation))throw bad("缺陷关联不存在");snapshotOne(executionId,defectId,u);trace(d,p,executionId,"DETACH_DEFECT",u,Map.of("defect_id",defectId));}
  public List<Map<String,Object>> exportRows(String d,long p,Map<String,Object> b,AuthUser u){return list(d,p,nullable(b.get("physical_subsystem_id")),nullable(b.get("round_id")),nullable(b.get("cycle_id")),nullable(b.get("directory_id")),text(b.get("keyword"),200,"关键字"),strings(b.get("status")),nullable(b.get("executor_id")),text(b.get("defect_link"),20,"缺陷关联"),text(b.get("validity"),20,"案例有效性"),"case_code","ascending",new PageQuery(1,2000),u).records();}
  private void snapshot(long id,AuthUser u){for(Long defect:repository.activeDefectIds(with(p(u,null,0),"executionId",id)))snapshotOne(id,defect,u);} private void snapshotOne(long execution,long defect,AuthUser u){Map<String,Object> row=with(with(p(u,null,0),"executionId",execution),"defectId",defect);Map<String,Object> source=repository.snapshotSource(row);if(source!=null)row.putAll(source);repository.snapshotRelation(row);} private void syncAttachments(long id,Object raw,AuthUser u){Set<Long>wanted=ids(raw);for(Long attachment:repository.attachmentIds(with(p(u,null,0),"executionId",id)))if(!wanted.contains(attachment)){attachments.deleteBound(attachment,BUSINESS_TYPE,String.valueOf(id),u);repository.deleteAttachment(with(with(p(u,null,0),"executionId",id),"attachmentId",attachment));}int sort=0;for(Long attachment:wanted){if(attachments.get(attachment,u).fileSize()>50L*1024*1024)throw bad("单个附件不能超过50MB");Map<String,Object> row=with(with(p(u,null,0),"executionId",id),"attachmentId",attachment);if(!repository.attachmentExists(row)){row.put("id",next());row.put("sort",sort);attachments.bind(new AttachmentBindingCommand(attachment,BUSINESS_TYPE,String.valueOf(id),null),u);repository.insertAttachment(row);}sort++;}}
  private void trace(String d,long p,long id,String action,AuthUser u,Map<String,Object> detail){try{Map<String,Object> row=with(p(u,d,p),"executionId",id);row.put("id",next());row.put("action",action);row.put("detail",objectMapper.writeValueAsString(detail));repository.insertTrace(row);}catch(Exception ex){throw new BusinessException(ErrorCode.INTERNAL_ERROR,"执行轨迹写入失败");}}
  private void scope(String d,long p,AuthUser u){if(!DOMAINS.contains(d))throw bad("测试大类无效");if(!repository.projectExists(p(u,d,p)))throw bad("项目不存在或无权访问");} private void enabled(String d,long p,long system,long tenant){if(!repository.enabledSystemExists(p(tenant,d,p,"systemId",system)))throw bad("请选择已启用的参测系统");} private void round(long id,String d,long p,long tenant){if(!repository.roundExists(p(tenant,d,p,"roundId",id)))throw bad("测试轮次不存在");} private void cycle(long id,String d,long p,long tenant){if(!repository.cycleExists(p(tenant,d,p,"cycleId",id)))throw bad("测试周期不存在");} private Map<String,Object> directory(long id,String d,long p,long tenant){Map<String,Object> row=repository.directory(p(tenant,d,p,"id",id));if(row==null)throw bad("执行目录不存在或不属于当前项目");return row;} private Map<String,Object> execution(long id,String d,long p,long tenant){Map<String,Object> row=repository.execution(p(tenant,d,p,"id",id));if(row==null)throw bad("执行记录不存在或不属于当前项目");return row;} private void writeAllowed(String d,long p,long system,AuthUser u){enabled(d,p,system,u.tenantId());if(!repository.mayWrite(p(u,d,p,"systemId",system))&&!authority("test-management:"+d+":execution:update"))throw new BusinessException(ErrorCode.FORBIDDEN,"未分配到该系统，不能填写执行结果");} private void manager(String d,AuthUser u){if(!authority("test-management:"+d+":execution:delete")&&!authority("test-management:"+d+":execution:update"))throw new BusinessException(ErrorCode.FORBIDDEN,"仅测试经理及以上可执行此操作");} private boolean authority(String a){var x=org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication();return x!=null&&x.getAuthorities().stream().anyMatch(v->a.equals(v.getAuthority()));}
  private static Map<String,Object> p(AuthUser u,String d,long project){Map<String,Object> row=p(u.tenantId(),d,project,null,null);row.put("userId",u.id());return row;} private static Map<String,Object> p(AuthUser u,String d,long project,String key,Object value){Map<String,Object> row=p(u,d,project);if(key!=null)row.put(key,value);return row;} private static Map<String,Object> p(long tenant,String d,long project,String key,Object value){Map<String,Object> row=new HashMap<>();row.put("tenantId",tenant);row.put("domain",d);row.put("projectId",project);row.put("userId",0L);if(key!=null)row.put(key,value);return row;} private static Map<String,Object> with(Map<String,Object> row,String key,Object value){row.put(key,value);return row;} private static long next(){return IDS.incrementAndGet();} private static long number(Object value){return ((Number)value).longValue();} private static boolean bool(Object value){return value instanceof Boolean b?b:"1".equals(String.valueOf(value))||"true".equalsIgnoreCase(String.valueOf(value));} private static String required(Object value,String label,int max){String result=text(value,max,label);if(result==null)throw bad(label+"不能为空");return result;} private static String text(Object value,int max,String label){if(value==null)return null;String result=String.valueOf(value).trim();if(result.isBlank()||"null".equals(result))return null;if(result.length()>max)throw bad(label+"不能超过"+max+"个字符");return result;} private static String html(Object value){String result=text(value,200000,"富文本");return result==null?null:result.replaceAll("(?is)<script[^>]*>.*?</script>","").replaceAll("(?i)\\son\\w+\\s*=\\s*(['\"]).*?\\1","");} private static String plain(String text){return text==null?"":text.replaceAll("<[^>]*>","").replace("&nbsp;"," ").trim();} private static String status(Object value){String result=required(value,"执行状态",24).toUpperCase(Locale.ROOT);if(!STATUSES.contains(result))throw bad("执行状态无效");return result;} private static Long nullable(Object value){if(value==null||String.valueOf(value).isBlank()||"null".equals(String.valueOf(value)))return null;try{return Long.parseLong(String.valueOf(value));}catch(Exception ex){throw bad("编号无效");}} private static long positive(Object value,String label){Long result=nullable(value);if(result==null||result<=0)throw bad(label+"无效");return result;} private static int integer(Object value){if(value==null||String.valueOf(value).isBlank())return 0;try{return Integer.parseInt(String.valueOf(value));}catch(Exception ex){throw bad("排序无效");}} private static List<?> list(Object value){return value instanceof Collection<?> c?new ArrayList<>(c):value==null?List.of():List.of(value);} private static Set<Long> ids(Object value){Set<Long> result=new LinkedHashSet<>();for(Object item:list(value))result.add(positive(item,"编号"));return result;} private static List<String> codes(Object value){List<String> result=new ArrayList<>();for(Object item:list(value))for(String code:String.valueOf(item).split("[,\\n\\r]+"))if(!code.trim().isEmpty())result.add(code.trim());return result;} private static List<String> strings(Object value){return list(value).stream().map(String::valueOf).toList();} @SuppressWarnings("unchecked") private static List<Map<String,Object>> maps(Object value){return value instanceof Collection<?> c?(List<Map<String,Object>>)(List<?>)new ArrayList<>(c):List.of();} private static BusinessException bad(String message){return new BusinessException(ErrorCode.BAD_REQUEST,message);} private static BusinessException conflict(String message){return new BusinessException(ErrorCode.CONFLICT,message);}
}
